// FailureRetrievalHooks declares complete-model read callbacks. Reference a local factory with retrieval=Factory on the model directive. The stored model is a read-only value; getters remain explicit.
type FailureRetrievalHooks struct {
	// Retrieved runs after successful stored hydration and row closure. The executor retains the caller's capability and wrappers; no write transaction is created implicitly. Return an error to stop this read. Nil is skipped.
	Retrieved func(context.Context, database.Executor, Failure) error
}

// FailureRetrievalObserver retains this model's concrete retrieval factory type. Names share the selected database's write/retrieval namespace.
type FailureRetrievalObserver = lifecycle.Observer[Failure, FailureRetrievalHooks]

// NewFailureRetrievalObserver declares a typed retrieval observer without registering or constructing hooks.
func NewFailureRetrievalObserver(observer string) FailureRetrievalObserver {
	return lifecycle.NewRetrievalObserver[Failure, FailureRetrievalHooks](observer)
}

// RegisterFailureRetrievalObserver binds dependency construction to a database module. Its factory runs once per nonempty complete fetch/batch and selected model role; write hydration, DTOs and scalar reads skip it.
func RegisterFailureRetrievalObserver(registrar *foundation.Registrar, pool foundation.Key[*database.DB], observer FailureRetrievalObserver, construct func(foundation.Resolver) (func() FailureRetrievalHooks, error)) error {
	return database.RegisterObserver(registrar, pool, observer, construct)
}
func (FailureRetrievalHooks) foundryRetrievalHooks(ctx context.Context, observerSet lifecycle.Observers) (foundryquery.RetrievalHooks[Failure], error) {
	factories, err := lifecycle.RetrievalObserverFactories[Failure, FailureRetrievalHooks](observerSet)
	if err != nil {
		return foundryquery.RetrievalHooks[Failure]{}, err
	}
	var allHooks []FailureRetrievalHooks
	if err := ctx.Err(); err != nil {
		return foundryquery.RetrievalHooks[Failure]{}, err
	}
	for _, factory := range factories {
		if err := ctx.Err(); err != nil {
			return foundryquery.RetrievalHooks[Failure]{}, err
		}
		allHooks = append(allHooks, factory())
	}
	if err := ctx.Err(); err != nil {
		return foundryquery.RetrievalHooks[Failure]{}, err
	}
	return foundryquery.RetrievalHooks[Failure]{Retrieved: func(ctx context.Context, executor database.Executor, item Failure) error {
		for _, hooks := range allHooks {
			if err := ctx.Err(); err != nil {
				return err
			}
			if hooks.Retrieved != nil {
				if err := hooks.Retrieved(ctx, executor, item); err != nil {
					return err
				}
			}
		}
		return ctx.Err()
	}}, nil
}

